from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid event and id
    try:
        ServerSentEvent(event="test-event", id="test-id")
        print("Valid event and id passed")
    except ValidationError as e:
        print(f"Valid event and id failed: {e}")

    # Test event with newline
    try:
        ServerSentEvent(event="test\nevent")
        print("Event with newline should have failed")
    except ValidationError as e:
        print(f"Event with newline failed as expected: {e}")

    # Test event with carriage return
    try:
        ServerSentEvent(event="test\revent")
        print("Event with carriage return should have failed")
    except ValidationError as e:
        print(f"Event with carriage return failed as expected: {e}")

    # Test id with newline
    try:
        ServerSentEvent(id="test\nid")
        print("Id with newline should have failed")
    except ValidationError as e:
        print(f"Id with newline failed as expected: {e}")

    # Test id with carriage return
    try:
        ServerSentEvent(id="test\rid")
        print("Id with carriage return should have failed")
    except ValidationError as e:
        print(f"Id with carriage return failed as expected: {e}")

    # Test id with null character
    try:
        ServerSentEvent(id="test\0id")
        print("Id with null character should have failed")
    except ValidationError as e:
        print(f"Id with null character failed as expected: {e}")

if __name__ == "__main__":
    test_sse_validation()
